def comps_color(A,val,diag=False):
 h,w=A.shape; steps=[(1,0),(-1,0),(0,1),(0,-1)]
 if diag:steps +=[(1,1),(1,-1),(-1,1),(-1,-1)]
 seen=set(); out=[]
 for r,c in zip(*np.where(A==val)):
  if (r,c) in seen:continue
  q=deque([(int(r),int(c))]);seen.add((int(r),int(c))); comp=[]
  while q:
   x,y=q.popleft();comp.append((x,y))
   for dx,dy in steps:
    a,b=x+dx,y+dy
    if 0<=a<h and 0<=b<w and A[a,b]==val and (a,b) not in seen:
     seen.add((a,b));q.append((a,b))
  out.append(comp)
