def region_labels(A,target,source_colors=(6,8),steps=((1,0),(-1,0),(0,1),(0,-1))):
 h,w=A.shape; vis=set(); regmap=np.full((h,w),-1,int); regs=[]
 for r in range(h):
  for c in range(w):
   if A[r,c]==target or (r,c) in vis: continue
   q=deque([(r,c)]);vis.add((r,c)); reg=[]
   while q:
    x,y=q.popleft();reg.append((x,y))
    for dx,dy in steps:
     a,b=x+dx,y+dy
     if 0<=a<h and 0<=b<w and A[a,b]!=target and (a,b) not in vis:
      vis.add((a,b));q.append((a,b))
   idx=len(regs); regs.append(reg)
   for x,y in reg:regmap[x,y]=idx
 # describe seed counts
 info=[]
 for reg in regs:
  vals=Counter(int(A[x,y]) for x,y in reg)
  info.append((len(reg), {k:v for k,v in vals.items() if k in source_colors}))
 return regmap,regs,info

def wall_prediction(A,target,ca,cb,diag=False):
 steps=((1,0),(-1,0),(0,1),(0,-1))
 if diag:steps=steps+((1,1),(1,-1),(-1,1),(-1,-1))
 rm,regs,info=region_labels(A,target,(ca,cb),steps)
 labels=[]
 for i,reg in enumerate(regs):
  cnt=Counter(int(A[x,y]) for x,y in reg if A[x,y] in (ca,cb))
  # majority; only seed color if present, tie -> target
  if cnt[ca]>cnt[cb]: lab=ca
  elif cnt[cb]>cnt[ca]:lab=cb
  else:lab=target
  labels.append(lab)
 pred=A.copy()
 for r,c in zip(*np.where(A==target)):
  adj={labels[rm[a,b]] for dr,dc in steps for a,b in [(r+dr,c+dc)] if 0<=a<A.shape[0] and 0<=b<A.shape[1] and rm[a,b]>=0}
  if len(adj)==1:pred[r,c]=next(iter(adj))
  # if one region / all adj labels same -> paint; else leave target
 return pred,rm,labels,info
