def seeded_graph_labels(A,target,seed_set,colors,diag=False):
 # identify seed components composed only of values in seed_set, assign dominant color by pixel count
 h,w=A.shape
 steps=[(1,0),(-1,0),(0,1),(0,-1)]
 if diag: steps += [(1,1),(1,-1),(-1,1),(-1,-1)]
 seen=set();seeds=[]
 for r,c in zip(*np.where(np.isin(A,list(seed_set)))):
  r,c=int(r),int(c)
  if (r,c) in seen:continue
  q=deque([(r,c)]);seen.add((r,c));reg=[]
  while q:
   x,y=q.popleft();reg.append((x,y))
   for dx,dy in steps:
    a,b=x+dx,y+dy
    if 0<=a<h and 0<=b<w and A[a,b] in seed_set and (a,b) not in seen:
     seen.add((a,b));q.append((a,b))
  cnt=Counter(int(A[x,y]) for x,y in reg)
  lab=max(colors,key=lambda z:(cnt[z],-z))
  seeds.append((reg,lab,cnt))
 print('seeds:',[(len(r),lab,cnt) for r,lab,cnt in seeds])
 dists={}
 for _,lab,_ in seeds:
  if lab not in dists:dists[lab]=np.full((h,w),999,int)
  dist=dists[lab];q=deque()
  for reg,cl,_ in seeds:
   if cl!=lab:continue
   for x,y in reg:
    for dx,dy in steps:
     a,b=x+dx,y+dy
     if 0<=a<h and 0<=b<w and A[a,b]==target and dist[a,b]>1:
      dist[a,b]=1;q.append((a,b))
  while q:
   x,y=q.popleft()
   for dx,dy in steps:
    a,b=x+dx,y+dy
    if 0<=a<h and 0<=b<w and A[a,b]==target and dist[a,b]>dist[x,y]+1:
     dist[a,b]=dist[x,y]+1;q.append((a,b))
 pred=A.copy()
 for r,c in zip(*np.where(A==target)):
  vals=sorted((dist[r,c],cl) for cl,dist in dists.items())
  if len(vals)==1 or vals[0][0]<vals[1][0]:pred[r,c]=vals[0][1]
  else:pred[r,c]=target
 return pred,dists
